MOD = 998244353

def extended_gcd(a, b):
    if b == 0:
        return a, 1, 0
    else:
        g, x, y = extended_gcd(b, a % b)
        return g, y, x - y * (a // b)

def mod_inv(a):
    g, x, y = extended_gcd(a, MOD)
    return x % MOD

def expected_length(n, k, l):
    if k == 0:
        return 1 if n == 1 else 0

    # Calculate the length of the segments that cover n intervals
    covered_len = [n - i for i in range(1, min(n, k) + 1)]

    # Calculate the expected total length
    total_len = 0
    for i in range(min(n, k)):
        total_len += 1 / (i + 1) * sum(covered_len)

    return mod_inv(MOD) * total_len % MOD

