from collections import defaultdict
from math import factorial

# Function to calculate modular factorial
def modular_factorial_mod_q(r, q):
    if r == 0:
        return 1
    result = 1
    for i in range(1, r + 1):
        result = (result * i) % q
    return result

# Function to calculate number of valid permutations
def count_permutations_with_factorial_mod_q(N, A):
    q = 998244353
    sum_of_perms = 1
    cum_fact_sum = 0

    for i in range(len(A)):
        cum_fact_sum = (cum_fact_sum + (factorial(i + 1) * A[i]) % q) % q

    for i in range(len(A) - 1, 0, -1):
        for j in range(i, N):
            if A[(j - 1) % i] < A[(j - i) % i]:
                break
        else:
            sum_of_perms += modular_factorial_mod_q(i + 1, q) * (factorial(N // i) % q) % q
            sum_of_perms %= q
            cum_fact_sum = (cum_fact_sum + (factorial(i + 1) * A[i]) % q) % q

    return (sum_of_perms - cum_fact_sum) % q

T = int(input())
