def mergesort(base_chars):
    """
    Mergesort function to sort the list of base-strings.
    """
    def merge_sort(arr):
        if len(arr) <= 1:
            return arr
        pvt = arr[len(arr) // 2]
        left, right = merge_sort(arr[:len(arr)//2]), merge_sort(arr[len(arr)//2:])
        return merge(pvt, left, right)

    def merge(pvt, left, right):
        queue = deque()
        left_index, right_index = 0, 0
        longest_match = [0, 0]
        while left_index < len(left) and right_index < len(right):
            left_char, right_char = left[left_index], right[right_index]
            if pvt == left_char and pvt == right_char:
                best_match = max(left_match, [left_index + len(left), right_index + len(right)])
                left_index, right_index = best_match
                longest_match = best_match
            elif right_char > left_char:
                right_index = best_match
            else:
                left_index = best_match
            queue.append((left_index, right_index))
        if len(queue) > 1:
            queue.pop(queue.popleft()[-1])
        return [(left_max + right_max, left_index[-1] + right_index[-1]) for left_index, right_index in queue]

