        graph[v].add(u)

    visited = [False] * (m + 1)

    def dfs(node, prev=None):
        visited[node] = True
        stack = [node]
        while stack:
            start_node = stack[-1]
            # Forward traversal
            if start_node not in graph:
                return
            forward_traversal_stack = graph[start_node].copy()
            while forward_traversal_stack and not visited[forward_traversal_stack[0]]:
                node = forward_traversal_stack.pop()
                stack.append(node)
                visited[node] = True
            # Backward traversal
            for node in graph[start_node]:
                if not visited[node] and node != prev:
                    dfs(node, start_node)
            # Jump to the next valid node - MAXINT to avoid unexpected cartesian product constraint
            while forward_traversal_stack and start_node not in forward_traversal_stack:
                forward_traversal_stack.pop()
            if len(forward_traversal_stack) == 0:
                return
            # Out of loop, return
        return

    for _ in range(m):
