def is_valid_path(n, path1, path2):
    stack = []
    for move in path1:
        if move not in {"N", "S", "E", "W"}:
            return "NO"

        if move == "N":
            if stack and stack[-1] == "S":
                stack.pop()
            else:
                return "NO"

        if move == "W":
            if stack and stack[-1] == "E":
                stack.pop()
            else:
                return "NO"

        if move == "E":
            if stack and stack[-1] == "W":
                stack.pop()
            else:
                return "NO"

        if move == "S":
            if stack and stack[-1] == "N":
                stack.pop()
            else:
                return "NO"

        stack.append(move)

    for i in range(n-1):
        if path2[i] in {"N", "S", "E", "W"} and path2[i] != stack[i]:
            return "NO"

    return "YES"

