import sys

def construct_new_graph(n, m, edges):
    """
    Constructs a new graph with the same number of nodes and edges as the old graph.
    For each pair of nodes, there is no edge connecting them in the new graph if there is an edge in the old graph.
    Returns the new graph as `m` lines, where each line contains a description of an edge.
    If it is not possible to construct a new graph with the mentioned properties, returns -1.
    """
    if m % 2 != 0:
        return -1

    graph = {i: {} for i in range(1, n+1)}

    for u, v in edges:
        graph[u][v] = None
        graph[v][u] = None

    for i in range(1, n+1):
        for j in range(i+1, n+1):
            if j not in graph[i]:
                graph[i][j] = None
                graph[j][i] = None
            if i % 2 == 0 and j % 2 == 0:
                if j not in graph[i]:
                    graph[i][j] = None
                if j % 2 != 0:
                    graph[i][j] = None
            elif i % 2 != 0 and j % 2 != 0:
                if j not in graph[i]:
                    graph[i][j] = None

    return [(i, j) for i in graph for j in graph[i]]

