from heapq import heappop, heappush
from collections import defaultdict
from typing import List

def dijkstra(n: int, graph: List[List[int]], start: int) -> List[int]:
    distances = [float('inf')] * (n + 1)
    distances[start] = 0
    queue = [(0, start)]
    edge_to = defaultdict(list)
    while queue:
        distance, vertex = heappop(queue)
        if vertex in edge_to:
            for next_vertex, weight in graph[vertex]:
                if distance + weight < distances[next_vertex]:
                    distances[next_vertex] = distance + weight
                    edge_to[next_vertex] = edge_to[vertex]
                    heappush(queue, (distance + weight, next_vertex))
                elif distance + weight <= distances[next_vertex]:
                    edge_to[next_vertex].append((vertex, weight))
        else:
            for next_vertex, weight in graph[vertex]:
                if distance + weight < distances[next_vertex]:
                    distances[next_vertex] = distance + weight
                    edge_to[next_vertex] = [(vertex, weight)]
                    heappush(queue, (distance + weight, next_vertex))
    return distances[1:]

