import sys
from collections import defaultdict

class Graph:
    def __init__(self, vertices):
        self.vertices = vertices
        self.edges = defaultdict(list)
        self.weights = {}

    def add_edge(self, u, v, weight):
        self.edges[u].append(v)
        self.edges[v].append(u)
        self.weights[(u, v)] = weight
        self.weights[(v, u)] = weight

def kahns_topological_sort(graph):
    in_degree = {v: 0 for v in range(graph.vertices)}
    for v in range(1, graph.vertices):
        for neighbor in graph.edges[v]:
            in_degree[neighbor] += 1

    queue = [node for node, degree in in_degree.items() if degree == 0]
    topological_order = []

    while queue:
        u = queue.pop(0)
        topological_order.append(u)

        for v in graph.edges[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(topological_order) == graph.vertices:
        return topological_order
    else:
        return []

def calculate_max_cactus_beauty(graph, available_edges):
    cactus_vertices = kahns_topological_sort(graph)
    cactus_edges = [(u, v) for u in cactus_vertices for v in graph.edges[u] if v in cactus_vertices]

    max_beauty = 0
    for weight in range(1, 10001):
        current_beauty = sum(graph.weights[(u, v)] for u, v in available_edges) + weight * (len(cactus_vertices) - len(cactus_edges))

        for i in range(len(available_edges), len(graph.edges)):
            u, v, w = available_edges[i]
            if (u, v) not in graph.weights:
                continue
            available_edges.append((u, v, w + weight))
        available_edges = cactus_edges + available_edges[len(cactus_edges):]

        for u in range(len(cactus_vertices)):
            for v in cactus_vertices:
                if u == v:
                    continue
                if (u, v) not in graph.weights:
                    continue
                cactus_edges.append((cactus_vertices[u], cactus_vertices[v], graph.weights[(u, v)] + weight))

        cactus_edges.sort(key=lambda x: -x[2])

        for edge in cactus_edges:
            if edge[0] not in cactus_vertices:
                edge = (edge[-1], edge[0])
            current_beauty = max(current_beauty, sum(graph.weights.values()) + edge[2] * (len(cactus_vertices) - len(cactus_edges)) + weight * len(cactus_edges))
        available_edges = available_edges[len(cactus_edges):]

        max_beauty = max(max_beauty, current_beauty)

    return max_beauty

