import math

def dot_product(v1, v2):
    return v1[0] * v2[0] + v1[1] * v2[1]

def distance_points(p1, p2):
    return math.sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)

def within_polygon_polygon(point, polygon):
    inside = False
    for i in range(len(polygon)):
        if polynomial[i][0] == polynomial[i+1][0]:
            if point[0] == polynomial[i][0]:
                return True
        else:
            u = (point[1] - polynomial[i][1]) / (polynomial[i+1][1] - polygon[i][1])
            v = (polygon[i][0] - point[0]) / (polynomial[i+1][0] - polygon[i][0])
            if u < v:
                u = v
            if u < 0 or u > 1:
                continue
            if v < 0 or v > 1:
                continue
            if polynomial[i][1] * v > polygon[i+1][1] * u:
                continue
            p1 = polygon[i]
            p2 = polygon[i+1]
            if min(p1[1], p2[1]) < point[1] <= max(p1[1], p2[1]):
                if min(p1[0], p2[0]) > point[0] >= max(p1[0], p2[0]):
                    inside = not inside
    return inside

def polygon_distance(n_polygon, points):
    distance_list = []
    for point in points:
        if within_polygon_polygon(point, n_polygon):
            if not within_polygon_polygon([0, 0], n_polygon):
                distance = distance_points([0, 0], point)
            else:
                distance_list.append(distance_points([0, 0], point))
            if not within_polygon_polygon([0, 1], n_polygon):
                distance = distance_points(point, [1, 1])
            else:
                distance_list.append(distance_points(point, [1, 1]))
            area = 0
            for i in range(len(n_polygon) - 1):
                point1 = n_polygon[i]
                point2 = n_polygon[i+1]
                if point[0] - point1[0] * 2 == 0:
                    continue
                if dot_product([1, point[1] - point1[1]], [point[0] * 2, 1]) >= 0:
                    area += point1[0] * (point2[1] - point1[1]) - point2[0] * (point2[1] - point1[1])
            distance_list.append(abs(distance + area) / 2)
    return distance_list

def main():
    n, m = map(int, input().split())
    n_polygon = []
    for i in range(n):
        a, b = map(float, input().split())
        n_polygon.append((a, b))
    points = []
    for i in range(m):
        a, b =  map(float, input().split())
        points.append((a, b))
    for point in points:
        distance_list = polygon_distance(n_polygon, [point])
        print('%.8f' % (distance_list[points.index(point)]))

if __name__ == "__main__":
    main()
