def fibonacci():
    a, b = 1, 1
    yield a
    yield b
    while True:
        yield a + b
        a, b = b, a + b

def calculate_price(a, b, x, cost):
    cost_x = 0
    for n, num in enumerate(x, 1):
        cost_n = int((num - num % b + cost) / b) - 1
        min_ture_cost = 2 * cost_n - cost_x
        if n + 1 == x[-1]:
            min_ture_cost = 2 - cost_x
        cost_x += 1
        yield min_ture_cost

def answer(n, q, a, b, x):
    cost_x = 999999999999999999
    best_sequence = []
    best_price = float('inf')

    for n in fibonacci():
        if n > max(x):
            break

    for candidate in fibonacci():
        length_x = len(x)
        short_seq = x
        for i, num in enumerate(x):
            num = min(candidate, num)
            if num > q:
                break
            else:
                if num > short_seq[length_x - len(x) + i]:
                    short_seq = x
            if num > short_seq[length_x - len(x) + i]:
                break
        else:
            del short_seq[-len(x):]
        cost_x = int((q - cost_x) / b) if cost_x != 0 or n == 1 else 999999999999999999

        min_cost = 0
        if any(c % a == 0 for c in calculate_price(a, b, short_seq, cost_x)):
            min_cost = f"{cost_x / b:.10f}"
        if int(min_cost) == min_cost and int(min_cost) != cost_x:
            best_cost = min(min_cost, best_cost)
        elif int(min_cost) != cost_x:
            best_cost = min(min_cost, best_cost)
        else:
            if cost_x < best_cost:
                best_cost = cost_x
                best_sequence = best_seq[:]
        if best_cost == 0:
            break

    return best_sequence, f"{best_cost / b:.10f}"

