# factorials and their inverses modulo 998244353
MOD = 998244353
fact = [1] * 3002
ifact = [1] * 3002

def factorial_mod(n, mod):
    if n == 0 or n == 1:
        return 1
    fact[n] = (fact[n-1] * n) % mod
    return fact[n]

def inverse_factorial_mod(n, mod):
    inv_fact[n] = pow(fact[n], mod-2, mod)
    for j in range(n, 2999):
        inv_fact[n] = (inv_fact[n] * inv_fact[j]) % mod

def mod_inverse(x, m):
    return pow(x, m-2, m)

def combinations(n, r, mod):
    return (fact[n] * inv_fact[r]) % mod % mod

# function to calculate density and counting valid combinations
def calculate_density_and_combinations(n, c, densities):

    max_density = max(densities)
    fact_pow = [[1]*3002 for _ in range(3002)]

    for i in range(1,3002):
        fact_pow[i][0] = 1
        for j in range(1,i):
            fact_pow[i][j] = (fact_pow[i-1][j] + fact_pow[i-1][j-1]) % MOD

    # counting tables for DP
    states = [(0] * 3002 for _ in range(n+1)]
    states[0] = [1 for _ in range(1+c)]

    for i in range(1, n+1):
        for j in range(0, c+1):
            states[i][(j, 0)] = states[i-1][(j, 0)]

            if j < 1+c:
                for k in range(1, max_density+1):
                    states[i][(j, k)] = (
                        states[i-1][(j, k-1)] +
                        states[i-1][(j-k, k)] +
                        fact_pow[n-i + 1 - j + k][k]
                    ) % MOD

    result_counts = [0 for _ in range(max_density+2)]

    for k in range(max_density+2):
        for j in range(max(max(densities) + 1, 0), c+1):
            target_density = min(k, j)
            count = 0
            tmp = 1
            for i in range(k, j + 1):
                count += states[n][((i, k), target_density)]
                tmp *= combinations(i, k, MOD) * fact_pow[n-i+1+k] % MOD
            result_counts[k] += count * inv_fact[target_density] % MOD
            result_counts[k] %= MOD

    return result_counts[densities.index(max_density)]
